"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["68962"],{41029(e){e.exports=JSON.parse('{"id":"F319","slug":"forward-price-cost-of-carry","name":"Futures Price: Cost of Carry","subject":"Derivatives","section":"Derivatives","topic":"Pricing forwards and futures (cost of carry)","level":"Intermediate","aliases":["cost of carry","convenience yield","storage cost","fair value of a futures","basis"],"formula":{"latex":"F_{0}=S_{0}\\\\,e^{(r+u-y)T}","also":[],"text":"Futures price = Spot x e^((risk-free rate + storage cost - yield) x time)"},"symbols":[{"symbol":"S_0","meaning":"Spot price","unit":"money"},{"symbol":"r","meaning":"Risk-free rate (continuously compounded)","unit":"per year"},{"symbol":"u","meaning":"Storage and insurance cost as a share of the price, per year","unit":"per year"},{"symbol":"y","meaning":"Income yield: dividend yield for shares, convenience yield for commodities","unit":"per year"},{"symbol":"T","meaning":"Time to delivery","unit":"years"}],"when_to_use":"Use it to find the no-arbitrage futures price. Holding the asset costs interest and storage, and pays an income or convenience yield. The futures price equals the spot price grown at the net cost of carry. If the market price differs, buying the cheap one and selling the expensive one locks in a risk-free profit.","worked_example":{"problem":"Gold trades at 2,000. The risk-free rate is 4%, storage and insurance cost 0.5% a year and there is no yield. What is the 9-month futures price, and what would it be for a share index at 4,000 with a 1.8% dividend yield and no storage cost?","inputs":{"s":2000,"r":4,"u":0.5,"y":0,"t":0.75,"s2":4000,"y2":1.8},"steps":[{"label":"Net cost of carry = r + u - y","working":"0.04+0.005-0","value":"4.50%"},{"label":"Futures price = S x e^(carry x T)","working":"2000 x exp(0.045 x 0.75)","value":"2,068.65"},{"label":"Futures price minus spot","working":"2068.65-2000","value":"68.65"},{"label":"Index futures price = S2 x e^((r - y2) x T)","working":"4000 x exp((0.04-0.018) x 0.75)","value":"4,066.55"},{"label":"Index futures price minus spot","working":"4066.55-4000","value":"66.55"}],"answer":"The 9-month gold futures price is 2,068.65, a basis of 68.65 above spot. The index futures price is 4,066.55, which is 66.55 above spot, since the dividend yield offsets part of the interest cost."},"calculator":{"available":true,"inputs":[{"id":"s","label":"Spot price","unit":"money","type":"number","default":2000,"hint":""},{"id":"r","label":"Risk-free rate","unit":"%","type":"number","default":4,"hint":""},{"id":"u","label":"Storage cost","unit":"%","type":"number","default":0.5,"hint":""},{"id":"y","label":"Yield (dividend or convenience)","unit":"%","type":"number","default":0,"hint":""},{"id":"t","label":"Time to delivery","unit":"years","type":"number","default":0.75,"hint":"","min":0.01},{"id":"s2","label":"Index spot (second example)","unit":"money","type":"number","default":4000,"hint":""},{"id":"y2","label":"Index dividend yield","unit":"%","type":"number","default":1.8,"hint":""}],"checks":[],"steps":[{"id":"carry","label":"Net cost of carry = r + u - y","expr":"r+u-y","format":"pct2"},{"id":"f","label":"Futures price = S x e^(carry x T)","expr":"s*exp(carry*t)","format":"money"},{"id":"basis","label":"Futures price minus spot","expr":"f-s","format":"money"},{"id":"f2","label":"Index futures price = S2 x e^((r - y2) x T)","expr":"s2*exp((r-y2)*t)","format":"money"},{"id":"basis2","label":"Index futures price minus spot","expr":"f2-s2","format":"money"}],"results":["f","f2"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"f":2068.6519858090214,"f2":4066.5475071442224}},"finder":{"finds":"The no-arbitrage futures price","needs":"Spot, rate, storage cost, yield, time"},"related":[{"slug":"forward-contract-value","name":"Forward Contract: Fair Price, Value and Payoff"},{"slug":"commodity-roll-yield","name":"Commodity Futures: Basis and Roll Yield"},{"slug":"continuous-compounding","name":"Continuous Compounding"}],"related_ids":["F317","F323","F027"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>F</mi><mn>0</mn></msub><mo>=</mo><msub><mi>S</mi><mn>0</mn></msub><mtext>\u2009</mtext><msup><mi>e</mi><mrow><mo stretchy=\\"false\\">(</mo><mi>r</mi><mo>+</mo><mi>u</mi><mo>\u2212</mo><mi>y</mi><mo stretchy=\\"false\\">)</mo><mi>T</mi></mrow></msup></mrow><annotation encoding=\\"application/x-tex\\">F_{0}=S_{0}\\\\,e^{(r+u-y)T}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"futures-margin-account","name":"Futures Daily Settlement and Margin Account"},"next":{"slug":"fx-forward-hedge","name":"FX Forward Hedge and Covered Interest Parity"},"lesson":null,"total":522}')}}]);